/**
 * Build-time constant injected by angular.json `define`.
 *
 * `false` for the default (production) build, `true` for the `mockup`
 * configuration. Because it is a literal substitution rather than a runtime
 * flag, every `if (COLOSSUS_PREVIEW) { ... }` branch is dead-code-eliminated
 * from the production bundle.
 */
declare const COLOSSUS_PREVIEW: boolean;
